from django.contrib import admin

from apps.core.admin import ReadOnlyAdminMixin

from .models import Report

# =============================================================================
# Reports (generated by the system, so view-only)
# =============================================================================


@admin.register(Report)
class ReportAdmin(ReadOnlyAdminMixin, admin.ModelAdmin):
    list_display = (
        "period_start",
        "period_end",
        "period_type",
        "recipient",
        "student",
        "group",
        "generated_at",
    )
    list_filter = ("period_type",)
    search_fields = (
        "recipient__full_name",
        "recipient__phone_number",
        "student__user__full_name",
        "group__name",
    )
    list_select_related = ("recipient", "student__user", "group")
    date_hierarchy = "period_start"
